import type { PermissionCode } from "./authorization";

export type SuperAdminBehavior =
  | "self"
  | "global_read"
  | "admin_override"
  | "deny_personal";

interface ProtectedOperationPermission {
  readonly operation: `${"GET" | "POST" | "PUT" | "PATCH" | "DELETE"} /${string}`;
  readonly permission: PermissionCode;
}

export interface ProtectedOperation extends ProtectedOperationPermission {
  readonly superAdminBehavior: SuperAdminBehavior;
}

