function behaviorAt(index: number): SuperAdminBehavior {
  const behavior = SUPER_ADMIN_BEHAVIORS[index];
  if (!behavior) throw new Error("Protected operation behavior mirror is incomplete.");
  return behavior;
}

export const PROTECTED_OPERATIONS: readonly ProtectedOperation[] = Object.freeze(
  PROTECTED_OPERATION_PERMISSIONS.map((entry, index) =>
    Object.freeze({ ...entry, superAdminBehavior: behaviorAt(index) })
  )
);

